import{_ as l,o as i,c as r,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"CDS G/H (Day 1) -  Calamari Intro","description":"","frontmatter":{"title":"CDS G/H (Day 1) -  Calamari Intro","date":"2014-06-24T00:00:00.000Z","updated":"2014-06-24T00:00:00.000Z","tags":["Ceph","Calamari","Distributed Storage","User Interface","API Integration"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_1_-_Calamari_Intro.md","filePath":"posts/2014/CDS_G_H_Day_1_-_Calamari_Intro.md","lastUpdated":1780459816000}'),o={name:"posts/2014/CDS_G_H_Day_1_-_Calamari_Intro.md"};function e(n,a,s,C,_,p){return i(),r("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Calamari 分布式存储介绍及开发讨论</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： John Spray, Gregory Meighan, 以及其他相关人员</p><p><strong>会议内容</strong>：</p><p><strong>1. Calamari 介绍</strong></p><ul><li>Calamari 是一个基于 JavaScript 的用户界面，通过 HTTP 与 Calamari 服务器通信。</li><li>Calamari 服务器负责处理前端功能，包括 Apache、Graphite、Calamari REST 和 Calamari Web。</li><li>Lulu 是 Calamari 的业务逻辑组件，负责远程操作和进度检查。</li><li>SaltStack 用于远程操作和配置管理。</li><li>Calamari 通过 VAR 和 Liberate 与 Ceph 集群接口通信。</li></ul><p><strong>2. Calamari 与 Ceph API 的关系</strong></p><ul><li>Calamari 与 Ceph REST API 有重叠，但提供更高级别的视图和功能。</li><li>Calamari API 简化与 Ceph 的集成，并提供更易于使用的工具。</li></ul><p><strong>3. Calamari 的部署</strong></p><ul><li>Calamari 的部署复杂，需要处理许多依赖项。</li><li>社区正在努力简化 Calamari 的部署，包括打包和测试。</li><li>Calamari 的部署需要依赖较新的软件版本，例如 SaltStack。</li></ul><p><strong>4. Calamari 用户界面</strong></p><ul><li>Calamari 提供直观的用户界面，用于监控和管理工作负载。</li><li>用户界面包括仪表板、OSD 工作台、主机视图、集群配置、池管理和存储池视图。</li><li>Calamari 支持扩展，可以通过编写额外的 Python 服务来实现。</li></ul><p><strong>5. Calamari 的扩展</strong></p><ul><li>Calamari 使用现有的插件接口，例如 SaltStack 和 Django。</li><li>可以通过编写额外的 Python 服务来扩展 Calamari 的功能。</li></ul><p><strong>6. 讨论要点</strong></p><ul><li>如何简化 Calamari 的部署。</li><li>如何提高 Calamari 的安全性，例如通过角色访问控制。</li><li>如何扩展 Calamari 的功能。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>社区将共同努力简化 Calamari 的部署。</li><li>Calamari 团队将继续开发新的功能，并提高 Calamari 的安全性。</li><li>Calamari 社区将继续讨论和改进 Calamari。</li></ul>',19)])])}const u=l(o,[["render",e]]);export{g as __pageData,u as default};
